import React from 'react';

export interface IconProps extends React.SVGProps<SVGSVGElement> {
  size?: number | string;
}

// Icon set sourced from coolicons (https://github.com/krystonschwarze/coolicons, CC BY 4.0),
// with a handful of custom-drawn icons (Brain, Eraser, Smile, Sparkles, Target, Trophy, Zap)
// for concepts the set doesn't cover, kept in the same 24x24 / 2px-stroke style.
const makeIcon = (inner: React.ReactNode) =>
  React.forwardRef<SVGSVGElement, IconProps>(({ size = 24, ...props }, ref) => (
    <svg
      ref={ref}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      {...props}
    >
      {inner}
    </svg>
  ));


